mapper.select:
select * from QA_FA_TEMPLATE where STATUS = 'ACTIVE'
and PROCESS_CODE = #{processCode}
order by PROCESS_CODE, VERSION desc

select * from QA_FA_TEMPLATE_SECTION
where TEMPLATE_ID = #{templateId}
order by SORT_NO

select * from QA_FA_TEMPLATE_ITEM
where TEMPLATE_ID = #{templateId}
order by SORT_NO

mapper.update:
update QA_FA_TEMPLATE
set STATUS = 'INACTIVE',
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = #{updateTime}
where PROCESS_CODE = #{processCode}
  and STATUS = 'ACTIVE'

mapper.insert:
insert into QA_FA_TEMPLATE (
  ID, PROCESS_CODE, PROCESS_NAME, VERSION, NAME, SOP_REF, STATUS,
  VALID_FROM, VALID_TO, REMARK, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME
) values (
  #{id}, #{processCode}, #{processName}, #{version}, #{name}, #{sopRef}, #{status},
  #{validFrom}, #{validTo}, #{remark}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}
)

insert into QA_FA_TEMPLATE_SECTION (
  ID, TEMPLATE_ID, CODE, NAME, SORT_NO, REMARK,
  STAGE_CODE, STAGE_NAME, STAGE_SORT_NO, STAGE_ENABLED, FINAL_REQUIRED, RELEASE_ON_PASS
) values (
  #{id}, #{templateId}, #{code}, #{name}, #{sortNo}, #{remark},
  #{stageCode}, #{stageName}, #{stageSortNo}, #{stageEnabled}, #{finalRequired}, #{releaseOnPass}
)

insert into QA_FA_TEMPLATE_ITEM (
  ID, TEMPLATE_ID, SECTION_ID, CODE, NAME, TOOL, STANDARD_TEXT, INPUT_TYPE,
  UNIT, RULE_JSON, FILL_ROLE, REQUIRED, CRITICAL, SORT_NO, REMARK
) values (
  #{id}, #{templateId}, #{sectionId}, #{code}, #{name}, #{tool}, #{standardText}, #{inputType},
  #{unit}, #{ruleJson}, #{fillRole}, #{required}, #{critical}, #{sortNo}, #{remark}
)
